function generateFPSMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const width = 500;
    const height = 500;
    const cellSize = 10;
    const mapWidth = width / cellSize;
    const mapHeight = height / cellSize;

    let map = Array.from({ length: mapHeight }, () => Array(mapWidth).fill(0));

    function drawMap() {
        for (let y = 0; y < mapHeight; y++) {
            for (let x = 0; x < mapWidth; x++) {
                if (map[y][x] === 1) {
                    ctx.fillStyle = 'black';
                    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
                } else if (map[y][x] === 2) {
                    ctx.fillStyle = 'gray';
                    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
                } else if (map[y][x] === 3) {
                    ctx.fillStyle = 'green';
                    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
                } else if (map[y][x] === 4) {
                    ctx.fillStyle = 'red';
                    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
                }
            }
        }
    }

    function floodFill(x, y) {
        if (x < 0 || x >= mapWidth || y < 0 || y >= mapHeight || map[y][x] !== 2) return;
        map[y][x] = 5;
        floodFill(x + 1, y);
        floodFill(x - 1, y);
        floodFill(x, y + 1);
        floodFill(x, y - 1);
    }

    function generateRooms() {
        for (let i = 0; i < 20; i++) {
            const startX = Math.floor(Math.random() * mapWidth) * cellSize;
            const startY = Math.floor(Math.random() * mapHeight) * cellSize;
            const roomWidth = Math.floor(Math.random() * 50) + 10;
            const roomHeight = Math.floor(Math.random() * 50) + 10;
            for (let y = startY; y < startY + roomHeight; y++) {
                for (let x = startX; x < startX + roomWidth; x++) {
                    if (x >= 0 && x < mapWidth && y >= 0 && y < mapHeight) {
                        map[Math.floor(y / cellSize)][Math.floor(x / cellSize)] = 2;
                    }
                }
            }
        }
    }

    function generateCorridors() {
        for (let i = 0; i < 30; i++) {
            const startX = Math.floor(Math.random() * mapWidth) * cellSize;
            const startY = Math.floor(Math.random() * mapHeight) * cellSize;
            const endX = Math.floor(Math.random() * mapWidth) * cellSize;
            const endY = Math.floor(Math.random() * mapHeight) * cellSize;
            const dx = Math.sign(endX - startX);
            const dy = Math.sign(endY - startY);
            let currentX = startX;
            let currentY = startY;
            while (currentX !== endX || currentY !== endY) {
                map[Math.floor(currentY / cellSize)][Math.floor(currentX / cellSize)] = 2;
                if (Math.abs(currentX - endX) > Math.abs(currentY - endY)) {
                    currentX += dx;
                } else {
                    currentY += dy;
                }
            }
        }
    }

    function placeSpawnPoints() {
        for (let i = 0; i < 2; i++) {
            let valid = false;
            while (!valid) {
                const x = Math.floor(Math.random() * mapWidth);
                const y = Math.floor(Math.random() * mapHeight);
                if (map[y][x] === 2) {
                    map[y][x] = 3;
                    valid = true;
                }
            }
        }
    }

    function placeWeaponPickups() {
        for (let i = 0; i < 5; i++) {
            let valid = false;
            while (!valid) {
                const x = Math.floor(Math.random() * mapWidth);
                const y = Math.floor(Math.random() * mapHeight);
                if (map[y][x] === 2) {
                    map[y][x] = 4;
                    valid = true;
                }
            }
        }
    }

    function ensureReachability() {
        let reachable = false;
        for (let y = 0; y < mapHeight; y++) {
            for (let x = 0; x < mapWidth; x++) {
                if (map[y][x] === 3) {
                    floodFill(x, y);
                    reachable = true;
                    break;
                }
            }
            if (reachable) break;
        }
        if (!reachable) {
            placeSpawnPoints();
            floodFill(0, 0);
        }
    }

    function generateNewMap() {
        map = Array.from({ length: mapHeight }, () => Array(mapWidth).fill(0));
        generateRooms();
        generateCorridors();
        placeSpawnPoints();
        placeWeaponPickups();
        ensureReachability();
        drawMap();
    }

    generateNewMap();

    const button = document.createElement('button');
    button.textContent = 'Generate New Map';
    button.addEventListener('click', generateNewMap);
    document.body.appendChild(button);

    const legend = document.createElement('div');
    legend.innerHTML = '<strong>Legend:</strong><br>' +
                      'Black: Walls<br>' +
                      'Gray: Floors<br>' +
                      'Green: Spawn Points<br>' +
                      'Red: Weapon Pickups';
    document.body.appendChild(legend);
}
